import { useCallback, useEffect } from 'react';
import { useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import { getAddressBarInputElement } from '@common/utils/address-bar-focus';

import { selectIsModalOpen } from '@common/slices/modal';

import { focusManager } from '../services/focus-manager';
import { type FocusSource, FOCUS_PRIORITY } from '../types/focus';

/**
 * React hook wrapper for the FocusManager service.
 *
 * Automatically manages blockers based on modal state and provides
 * convenient methods for requesting focus on different targets.
 *
 * @example
 * ```typescript
 * const { focusView, focusAddressBar } = useFocusManager();
 *
 * // Focus a view when user clicks a tab
 * const handleTabClick = (viewIdentity: OpenFin.Identity) => {
 *   focusView(viewIdentity, 'user-click');
 * };
 * ```
 */
export const useFocusManager = () => {
    // Use the selector which now safely handles both store structures
    const isModalOpen = useSelector(selectIsModalOpen);

    // Automatically manage modal blocker
    useEffect(() => {
        if (isModalOpen) {
            // Add blocker immediately to prevent focus escape during modal transitions
            focusManager.addBlocker('modal');
            return () => {
                focusManager.removeBlocker('modal');
            };
        }

        // When modal closes, immediately remove blocker
        focusManager.removeBlocker('modal');
    }, [isModalOpen]);

    /**
     * Request focus on a view
     * @param identity - The OpenFin view identity
     * @param source - The source of the focus request
     */
    const focusView = useCallback((identity: OpenFin.Identity, source: FocusSource = 'programmatic') => {
        focusManager.requestFocus({
            target: { type: 'view', identity },
            priority: FOCUS_PRIORITY.VIEW,
            source
        });
    }, []);

    /**
     * Request focus on the address bar
     */
    const focusAddressBar = useCallback(() => {
        focusManager.requestFocus({
            target: { type: 'addressBar' },
            priority: FOCUS_PRIORITY.ADDRESS_BAR,
            source: 'programmatic'
        });
    }, []);

    /**
     * Request focus on the current window
     */
    const focusWindow = useCallback(() => {
        focusManager.requestFocus({
            target: { type: 'window' },
            priority: FOCUS_PRIORITY.VIEW,
            source: 'programmatic'
        });
    }, []);

    /**
     * Blur the address bar
     */
    const blurAddressBar = useCallback(() => {
        const addressBar = getAddressBarInputElement();
        if (addressBar) {
            addressBar.blur();
        }
    }, []);

    /**
     * Clear the current focus state
     */
    const clearFocus = useCallback(() => {
        focusManager.clearFocus();
    }, []);

    return {
        focusView,
        focusAddressBar,
        focusWindow,
        blurAddressBar,
        clearFocus,
        focusManager // Expose for advanced use cases
    };
};
