import { useCallback, useEffect, useState } from 'react';

import { OpenFin } from '@openfin/core';

import debounce from 'lodash.debounce';

import { SearchMenuChannelResponse } from '@common/utils/popup-window';
import { getOFWindow, WindowName } from '@common/utils/window';

import { COMMAND_BAR_HEIGHT, SEARCH_PROVIDER_TAB_HEIGHT } from '@enterprise/components/ControlBar/SearchMenu/utils';
import { CONTROL_BAR_HEIGHT } from '@enterprise/components/ControlBar/utils';

import { useIsWindows } from '@enterprise/hooks/useIsWindows';

import { getSearchMenuHeight, getSearchMenuWidth } from './getDimensions';

/* Static values coming from design spec. */
export const MENU_BOUNDS = {
    expanded: {
        minWidth: 376,
        maxWidth: 728
    },
    emptySearchInputContainer: {
        minHeight: 408,
        maxHeight: 518 + SEARCH_PROVIDER_TAB_HEIGHT
    },
    percentOfParentWidth: 0.7,
    resultsContainerMaxHeight: 475 + COMMAND_BAR_HEIGHT + SEARCH_PROVIDER_TAB_HEIGHT, // total height should be 588 - 40 (height of the search input container)
    parentWindowHeightOffset: 40 + CONTROL_BAR_HEIGHT
};

/**
 * Custom hook to adjust the dimensions of the search menu view based on various conditions. The search menu will expand and collapse when opened or closed.
 * When open, the search menu will expand to include all of the content (either results or curated content) until the height reaches the maximum.
 * The search menu dimensions are sent to the browser window, where the view is resized accordingly.
 *
 * This hook also listens for resize events on the parent window to adjust the search menu view dimensions accordingly.
 *
 * @param {React.RefObject<HTMLElement>} containerRef - Ref object pointing to the container element of the search menu.
 * @param {boolean} shouldExpand - Boolean indicating if the search results view should expand.
 * @param {React.RefObject<BroadcastChannel>} searchMenuChannel - Ref object for the broadcast channel used to communicate with the browser window.
 * @param {boolean} shouldShowEmptySearchContainer - Boolean indicating if the emptySearchInputContainer container should be shown.
 * @param {number} offsetLeft - Number indicating the left offset for the search menu view derived from browser input container ref.
 */
const useAdjustSearchMenuViewDimensions = (
    containerRef: React.RefObject<HTMLElement>,
    shouldExpand: boolean,
    searchMenuChannel: React.RefObject<BroadcastChannel>,
    shouldShowEmptySearchContainer: boolean,
    offsetLeft: number
) => {
    // Windows has 1px window border, so we need an extra 1px from the top
    const isWindows = useIsWindows();
    const offsetTop = CONTROL_BAR_HEIGHT + (isWindows ? 2 : 1);
    const [viewBounds, setViewBounds] = useState<{ height: number; width: number }>({ height: 0, width: 0 });

    const adjustViewDimensions = useCallback(
        async (container: HTMLElement) => {
            if (searchMenuChannel.current && shouldExpand) {
                const parentName = fin.me.name.replace(WindowName.BrowserAddressSearchPrefix, '');
                const { width: parentWindowWidth, height: parentWindowHeight } = await getOFWindow({
                    uuid: fin.me.uuid,
                    name: parentName
                }).getBounds({ boundsType: 'current' });

                const width = getSearchMenuWidth(parentWindowWidth);
                const height = getSearchMenuHeight(parentWindowHeight, shouldShowEmptySearchContainer, container);
                setViewBounds({ height, width });
            }
        },
        [searchMenuChannel, shouldShowEmptySearchContainer, shouldExpand]
    );

    useEffect(() => {
        const container = containerRef.current;
        if (container) {
            // Call adjustViewDimensions immediately to set the initial dimensions
            adjustViewDimensions(container);

            // Reduces flickering when resizing the view
            const debounceAdjustViewDimensions = debounce(() => adjustViewDimensions(container), 100, {
                leading: true
            });

            const menuResizeObserver = new ResizeObserver(debounceAdjustViewDimensions);
            menuResizeObserver.observe(container);

            return () => menuResizeObserver.disconnect();
        }
    }, [containerRef, adjustViewDimensions]);

    useEffect(() => {
        if (shouldExpand) {
            (async () => {
                await (fin.me as OpenFin.View).showAt(
                    { ...viewBounds, top: offsetTop, left: offsetLeft },
                    { bringToFront: true }
                );

                searchMenuChannel.current.postMessage({
                    type: 'resize-view',
                    width: viewBounds.width
                } as SearchMenuChannelResponse);
            })();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [viewBounds]);

    useEffect(() => {
        const parentName = fin.me.name.replace(WindowName.BrowserAddressSearchPrefix, '');
        const parentWindow = getOFWindow({
            uuid: fin.me.uuid,
            name: parentName
        });

        const resizeHandler = async () => {
            await adjustViewDimensions(containerRef.current);
        };

        const setUpResizeListener = async () => {
            await parentWindow.addListener('bounds-changed', resizeHandler);
        };
        setUpResizeListener();

        return () => {
            parentWindow.removeListener('bounds-changed', resizeHandler);
        };
    }, [adjustViewDimensions]);
};

export default useAdjustSearchMenuViewDimensions;
