import { COMMAND_BAR_HEIGHT, SEARCH_PROVIDER_TAB_HEIGHT } from '@enterprise/components/ControlBar/SearchMenu/utils';

import { MENU_BOUNDS } from './useAdjustSearchMenuViewDimensions';

/**
 * @description Get the width of the search menu based on the parent window width and the expanded state of the menu
 * @param parentWindowWidth - The width of the parent window
 * @returns {number} The calculated width of the search menu
 */
export const getSearchMenuWidth = (parentWindowWidth: number): number => {
    let expandedWidth = parentWindowWidth * MENU_BOUNDS.percentOfParentWidth;
    if (expandedWidth > MENU_BOUNDS.expanded.maxWidth) {
        expandedWidth = MENU_BOUNDS.expanded.maxWidth;
    } else if (expandedWidth < MENU_BOUNDS.expanded.minWidth) {
        expandedWidth = MENU_BOUNDS.expanded.minWidth;
    }
    return Math.ceil(expandedWidth);
};

/**
 * @description Get the height of the search menu based on the parent window height, the expanded state of the menu, and the UI state of the menu
 * @param parentWindowHeight - The height of the parent window
 * @param shouldShowEmptySearchInputContainer - Whether the empty search input UI should be shown
 * @param container - The container for the search menu
 * @returns {number} The calculated height of the search menu
 */
export const getSearchMenuHeight = (
    parentWindowHeight: number,
    shouldShowEmptySearchInputContainer: boolean,
    container: HTMLElement
): number => {
    const resultsContainer = document.getElementById('results-container');
    const emptySearchInputContainer = document.getElementById('empty-search-input-container');

    const resultContainerMaxHeight =
        resultsContainer !== null
            ? Math.max(
                  container.scrollHeight,
                  // Heights of all of the contents of the Result Container UI.
                  resultsContainer.scrollHeight + COMMAND_BAR_HEIGHT + SEARCH_PROVIDER_TAB_HEIGHT
              )
            : container.scrollHeight;

    const emptySearchInputContainerHeight =
        emptySearchInputContainer !== null
            ? Math.min(
                  MENU_BOUNDS.emptySearchInputContainer.maxHeight,
                  // Heights of all of the contents of the Empty Search Input UI
                  emptySearchInputContainer.scrollHeight + SEARCH_PROVIDER_TAB_HEIGHT
              )
            : Math.min(container.scrollHeight, MENU_BOUNDS.emptySearchInputContainer.maxHeight);

    let height;
    /**
     * Remark: There always needs to be parentWindowHeightOffset amount of space between the search menu view and the bottom of the browser window.
     *
     * The code below does the following:
     *   - If the EmptySearchInputContainer is shown
     *     - If the browser window is not tall enough to show the entire EmptySearchInputContainer, then the height of the view
     *         is set to the maximum of the available space dictated by the browser window and the min height of the EmptySearchInputContainer.
     *         This ensures that the minimum height of the EmptySearchInputContainer is respected.
     *     - Else if the browser window is tall enough to show the entire EmptySearchInputContainer, then the height of the view
     *         is set to the height that the EmptySearchInputContainer needs to be to show all its content (Search Provider Tab, Feature Content, and Recents), without exceed the EmptySearchInputContainer max height.
     *   - Else if the ResultsContainer is shown
     *      - We set the the height of the view to the maximum height needed to show all the content of the ResultsContainer (Search Provider Tab, Results List, and Command Bar),
     *          while respecting the height bounds for the ResultsContainer and the height of the parent window.
     */
    if (shouldShowEmptySearchInputContainer) {
        const emptySearchContainerExceedsParentHeight =
            parentWindowHeight - MENU_BOUNDS.parentWindowHeightOffset < MENU_BOUNDS.emptySearchInputContainer.maxHeight;
        const emptySearchContainerContentMeetsMinHeight =
            emptySearchInputContainerHeight > MENU_BOUNDS.emptySearchInputContainer.minHeight;

        if (emptySearchContainerExceedsParentHeight && emptySearchContainerContentMeetsMinHeight) {
            height = Math.max(
                parentWindowHeight - MENU_BOUNDS.parentWindowHeightOffset,
                MENU_BOUNDS.emptySearchInputContainer.minHeight
            );
        } else {
            height = emptySearchInputContainerHeight;
        }
    } else {
        height = Math.min(
            resultContainerMaxHeight,
            MENU_BOUNDS.resultsContainerMaxHeight,
            parentWindowHeight - MENU_BOUNDS.parentWindowHeightOffset
        );
    }

    return height;
};
